import 'science_task_data.dart';

/// Additional topic-specific, answer-reviewed Austrian primary-school questions.
/// Earlier-grade revision alone must not stand in for third/fourth-grade content.
const List<ScienceQuestion> scienceQualityExtensionQuestions = [
  // Grade 3: weather and observation
  ScienceQuestion.item(3, 'Wetter', 'Womit misst man die Niederschlagsmenge?', 'mit einem Regenmesser', ['mit einer Uhr', 'mit einem Kompass', 'mit einem Lineal'], 'Ein Regenmesser sammelt Regen. Die Menge wird üblicherweise in Millimetern angegeben.'),
  // Den Temperaturunterschied ausrechnen ist Mathematik (Kl. 4 „Diagramme
  // lesen“); hier zählt, warum es mittags wärmer ist.
  ScienceQuestion.item(3, 'Wetter', 'Ein Thermometer zeigt morgens 7 Grad und mittags 14 Grad. Warum ist es mittags wärmer?', 'Die Sonne steht höher und wärmt stärker.', ['Am Mittag ist der Mond näher bei uns.', 'Das Thermometer ist mittags kaputt.', 'Mittags weht immer ein eiskalter Nordwind.'], 'Zu Mittag steht die Sonne hoch am Himmel. Ihre Strahlen wärmen Boden und Luft stärker als am Morgen.'),
  ScienceQuestion.item(3, 'Wetter', 'Wofür steht ein Pfeil auf einer Wetterkarte meist?', 'für die Windrichtung', ['für die Uhrzeit', 'für das Datum', 'für die Einwohnerzahl'], 'Wetterkarten können die Windrichtung mit Pfeilen darstellen.'),
  ScienceQuestion.item(3, 'Wetter', 'Warum soll man bei Gewitter Schutz in einem Gebäude suchen?', 'weil Blitze gefährlich sind', ['weil Regen immer giftig ist', 'weil Wolken herunterfallen', 'weil Wind die Sonne löscht'], 'Bei Gewitter sind Gebäude ein besserer Schutz als offene Flächen oder einzelne Bäume.'),

  // Grade 3: safe mobility
  ScienceQuestion.item(3, 'Verkehr', 'Ein parkendes Auto verdeckt die Sicht auf die Straße. Was ist sicher?', 'an einer übersichtlichen Stelle queren', ['schnell zwischen den parkenden Autos rennen', 'direkt davor auf die Fahrbahn laufen', 'mit geschlossenen Augen gehen'], 'Überquere Straßen nur dort, wo du Fahrzeuge frühzeitig sehen kannst.'),
  ScienceQuestion.item(3, 'Verkehr', 'Warum hält man besonders Abstand zu abbiegenden Lastwagen?', 'weil man im toten Winkel übersehen werden kann', ['weil Lastwagenreifen beim Abbiegen immer platzen', 'weil an jeder Kreuzung die Ampeln fehlen', 'weil Lastwagen beim Abbiegen keine Bremsen haben'], 'Große Fahrzeuge haben Bereiche, die der Fahrer schwer einsehen kann.'),
  ScienceQuestion.item(3, 'Verkehr', 'Du willst mit dem Fahrrad links abbiegen. Was musst du beachten?', 'rechtzeitig schauen und sicher einordnen', ['einfach ohne Schauen abbiegen', 'die Augen schließen', 'auf dem Gehsteig schneller werden'], 'Schau zurück, gib ein Handzeichen und ordne dich rechtzeitig ein. Unter 12 Jahren fährst du auf der Straße nur mit einer Begleitperson – außer du hast den Radfahrausweis.'),
  ScienceQuestion.item(3, 'Verkehr', 'Was hilft bei Regen, damit andere dich im Straßenverkehr besser sehen?', 'Reflektoren und gut sichtbare Kleidung', ['nur dunkle Kleidung', 'ohne Licht fahren', 'überall schneller laufen'], 'Reflektierende Elemente und passende Beleuchtung verbessern die Sichtbarkeit.'),

  // Grade 3: time and calendar
  ScienceQuestion.item(3, 'Zeit und Kalender', 'Wie viele Minuten ergeben eine Dreiviertelstunde?', '45 Minuten', ['15 Minuten', '30 Minuten', '75 Minuten'], 'Eine Stunde hat 60 Minuten, drei Viertel davon sind 45 Minuten.'),
  ScienceQuestion.item(3, 'Zeit und Kalender', 'Wie viele Tage hat ein normales Jahr?', '365', ['300', '356', '360'], 'Ein normales Jahr hat 365 Tage, ein Schaltjahr 366.'),
  ScienceQuestion.item(3, 'Zeit und Kalender', 'Wie viele Tage hat der Februar in einem Schaltjahr?', '29', ['27', '28', '30'], 'In einem Schaltjahr hat der Februar 29 statt 28 Tage.'),
  ScienceQuestion.item(3, 'Zeit und Kalender', 'Wie viele Wochen sind genau 21 Tage?', '3 Wochen', ['2 Wochen', '4 Wochen', '7 Wochen'], 'Eine Woche dauert sieben Tage. 21 geteilt durch 7 ist 3.'),
  // Ende einer Zeitspanne berechnen übt Mathematik („Uhr-Abenteuer“).
  ScienceQuestion.item(3, 'Zeit und Kalender', 'Wozu hilft dir ein Stundenplan?', 'Er zeigt, wann welches Fach dran ist.', ['Er zeigt, wie das Wetter morgen wird.', 'Er zeigt den kürzesten Weg zur Schule.', 'Er zählt alle Tage bis zu den Ferien.'], 'Im Stundenplan steht für jeden Schultag, in welcher Stunde welches Fach ist.'),

  // Grade 3: living together
  ScienceQuestion.item(3, 'Familie und Gemeinschaft', 'Eine Klasse möchte über das nächste Ausflugsziel entscheiden. Wie geht das fair?', 'Vorschläge sammeln und abstimmen', ['nur das lauteste Kind entscheiden lassen', 'niemanden fragen', 'die Vorschläge verstecken'], 'Beim Abstimmen können alle ihre Stimme abgeben.'),
  ScienceQuestion.item(3, 'Familie und Gemeinschaft', 'Was bedeutet es, eine gemeinsame Regel zu vereinbaren?', 'alle kennen und beachten sie', ['nur einer darf die Regel kennen', 'die Regel gilt nie', 'Regeln werden heimlich geändert'], 'Gemeinsame Regeln helfen beim fairen Zusammenleben.'),
  ScienceQuestion.item(3, 'Familie und Gemeinschaft', 'Ein Kind versteht die Spielregeln noch nicht. Was hilft?', 'ruhig erklären und gemeinsam probieren', ['das Kind auslachen', 'einfach ohne es weiterspielen', 'alle Regeln absichtlich ändern'], 'Geduld und Erklären ermöglichen allen das Mitmachen.'),
  ScienceQuestion.item(3, 'Familie und Gemeinschaft', 'Zwei Kinder sind unterschiedlicher Meinung. Welcher Weg hilft?', 'zuhören und eine Lösung suchen', ['den Streit an alle anderen weitergeben', 'einander anschreien', 'Sachen kaputtmachen'], 'Zuhören und Kompromisse finden kann Konflikte lösen.'),
  ScienceQuestion.item(3, 'Familie und Gemeinschaft', 'Warum teilen wir Aufgaben bei einem Gruppenprojekt auf?', 'damit alle sinnvoll mitarbeiten können', ['damit niemand helfen darf', 'damit ein Kind alle Arbeit hat', 'damit nichts fertig wird'], 'Aufgabenteilung nutzt die Stärken aller Gruppenmitglieder.'),

  // Grade 3: work and society
  ScienceQuestion.item(3, 'Berufe', 'Wer plant, wie ein Haus sicher gebaut werden kann?', 'eine Bauingenieurin oder ein Bauingenieur', ['eine Sängerin oder ein Sänger', 'eine Köchin oder ein Koch', 'eine Buchhändlerin oder ein Buchhändler'], 'Bauingenieurinnen und Bauingenieure berechnen und planen Bauwerke.'),
  ScienceQuestion.item(3, 'Berufe', 'Wer untersucht und behandelt kranke Tiere?', 'eine Tierärztin oder ein Tierarzt', ['eine Försterin oder ein Förster', 'eine Köchin oder ein Koch', 'eine Pilotin oder ein Pilot'], 'Tierärztinnen und Tierärzte behandeln kranke und verletzte Tiere.'),
  ScienceQuestion.item(3, 'Berufe', 'Was ist eine typische Aufgabe einer Tischlerin?', 'Holzmöbel herstellen und reparieren', ['das Wetter für morgen vorhersagen', 'Flugzeuge sicher steuern und landen', 'Zähne untersuchen und behandeln'], 'Tischlerinnen und Tischler bearbeiten Holz und bauen beispielsweise Möbel.'),
  ScienceQuestion.item(3, 'Berufe', 'Was braucht ein Mensch, der Lebensmittel verkauft, besonders?', 'sauberes Arbeiten und Hygiene', ['ungewaschene Hände', 'offene Lebensmittel am Boden', 'verdorbene Ware'], 'Hygiene schützt Kunden vor Krankheitserregern.'),
  ScienceQuestion.item(3, 'Berufe', 'Wofür ist die Müllabfuhr in einer Gemeinde wichtig?', 'sie sammelt und transportiert Abfälle', ['sie löscht Brände statt der Feuerwehr', 'sie malt neue Verkehrszeichen auf', 'sie verteilt die Zeugnisse der Schule'], 'Die Müllabfuhr trägt zur Sauberkeit und Abfallentsorgung bei.'),

  // Grade 3: plants
  ScienceQuestion.item(3, 'Pflanzen', 'Warum brauchen grüne Pflanzen Sonnenlicht?', 'sie nutzen Licht, um Nährstoffe herzustellen', ['damit die Erde leuchtet', 'damit die Wurzeln laufen', 'damit Wasser verschwindet'], 'Bei der Fotosynthese nutzen grüne Pflanzen Licht, Wasser und Kohlendioxid, um Zucker aufzubauen.'),
  ScienceQuestion.item(3, 'Pflanzen', 'Was kann einem Samen helfen zu keimen?', 'Wasser und eine passende Temperatur', ['nur ein Stein', 'nur trockene Luft', 'völlig gefrorener Boden'], 'Viele Samen keimen bei genügend Wasser, Sauerstoff und geeigneter Wärme.'),

  // Grade 4: Diagramme zu Wetter, Natur, Verkehr und Umwelt. Gefragt ist das
  // sachunterrichtliche Verständnis; Rechenfragen zu Diagrammen stehen seit
  // 26.11.2026 in Mathematik Kl. 4 „Diagramme lesen“ (Entscheidung Heinz).
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist ein Tag mit Frost.\nJänner: 🟦🟦🟦🟦🟦🟦🟦🟦🟦\nApril: 🟦🟦\nIn welchem Monat sind Wege und Pfützen öfter vereist?', 'im Jänner', ['im April', 'in beiden gleich oft', 'in keinem der beiden'], 'Frost heißt: Es hat unter 0 Grad und Wasser gefriert zu Eis. Im Jänner gab es viel mehr Frosttage.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist eine Stunde Tageslicht.\nDezember: 🟦🟦🟦🟦🟦🟦🟦🟦\nJuni: 🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦\nWarum ist es im Juni so viel länger hell?', 'Im Sommer sind die Tage länger.', ['Im Juni ist die Erde näher an der Sonne.', 'Im Juni gibt es mehr Wolken.', 'Im Dezember geht die Sonne nie auf.'], 'Im Sommer steht die Sonne höher, geht früher auf und später unter. Die Erde ist im Juni sogar etwas weiter von der Sonne entfernt als im Winter.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist ein Zentimeter.\nKresse, täglich gegossen: 🟦🟦🟦🟦🟦🟦\nKresse mit wenig Wasser: 🟦🟦\nWas zeigt dieser Versuch?', 'Kresse wächst mit genug Wasser besser.', ['Kresse wächst ohne Wasser am allerbesten.', 'Viel Wasser macht Pflanzen immer kleiner.', 'Kresse wächst nur im dunklen Schrank.'], 'Die gut gegossene Kresse ist 6 cm hoch, die andere nur 2 cm. Pflanzen brauchen Wasser, um zu keimen und zu wachsen.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist ein voller Müllsack unserer Klasse.\nPapier: 🟦🟦🟦🟦🟦🟦\nPlastik: 🟦🟦🟦\nRestmüll: 🟦\nWohin bringt die Klasse den größten Teil ihres Mülls?', 'zum Altpapier', ['in den Gelben Sack', 'in den Restmüll', 'in die Biotonne'], 'Die meisten Säcke sind Papier. Papier kommt zum Altpapier, daraus wird neues Papier.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 sind 10 Autos vor der Schule.\nvon 7 bis 8 Uhr: 🟦🟦🟦🟦🟦🟦🟦\nvon 9 bis 10 Uhr: 🟦🟦\nWann musst du am Zebrastreifen besonders aufmerksam sein?', 'von 7 bis 8 Uhr', ['von 9 bis 10 Uhr', 'nie, Autos halten immer', 'nur am Wochenende'], 'Zwischen 7 und 8 Uhr fahren die meisten Autos. Schau immer nach links und rechts, bei viel Verkehr ganz besonders.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 sind 5 Vögel am Futterhaus.\nJänner: 🟦🟦🟦🟦🟦🟦\nMai: 🟦\nWarum kommen im Winter mehr Vögel zum Futterhaus?', 'Sie finden draußen wenig Futter.', ['Im Winter haben Vögel keine Federn.', 'Im Mai schlafen alle Vögel tagsüber.', 'Das Futterhaus ist im Winter größer.'], 'Im Winter gibt es kaum Insekten, Beeren und Samen. Darum suchen Vögel dann Futterhäuser auf.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist ein Tag mit Gewitter.\nJänner: 🟦\nJuli: 🟦🟦🟦🟦🟦🟦🟦\nWarum gibt es im Sommer mehr Gewitter?', 'Warme, feuchte Luft steigt rasch auf.', ['Kalte Luft erzeugt immer neue Blitze.', 'Im Sommer ist die Luft ganz trocken.', 'Im Juli gibt es überhaupt keine Wolken.'], 'An heißen Tagen steigt warme, feuchte Luft schnell nach oben. Dort entstehen hohe Gewitterwolken.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 sind 10 Liter Wasser.\nDuschen: 🟦🟦🟦🟦\nBaden: 🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦\nWie sparst du laut Diagramm Wasser?', 'Ich dusche, statt zu baden.', ['Ich bade, statt zu duschen.', 'Ich lasse das Wasser laufen.', 'Ich bade zweimal am Tag.'], 'Duschen braucht hier 40 Liter, Baden 120 Liter. Kurz duschen spart Trinkwasser.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist ein Schultag, an dem es am Schulweg noch dunkel ist.\nOktober: 🟦🟦🟦\nDezember: 🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦\nWas ist im Dezember am Schulweg besonders wichtig?', 'helle Kleidung mit Reflektoren', ['dunkle Kleidung ohne Licht', 'Kopfhörer mit lauter Musik', 'schnell über die Straße laufen'], 'Im Dezember ist es am Morgen oft noch dunkel. Helle Kleidung und Reflektoren sehen Autofahrer schon von Weitem.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Lies das Diagramm. Ein 🟦 ist ein Kind mit Fahrradhelm.\nKlasse 4a: 🟦🟦🟦🟦🟦🟦🟦🟦\nKlasse 4b: 🟦🟦🟦\nIn beiden Klassen fahren 8 Kinder mit dem Rad. Worüber sollte die 4b sprechen?', 'warum ein Helm den Kopf schützt', ['wie man ohne Licht schneller fährt', 'warum Helme nur Schmuck sind', 'wie man freihändig abbiegt'], 'In der 4b fahren 5 Kinder ohne Helm. Ein passender Helm kann den Kopf bei einem Sturz schützen.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Ein Säulendiagramm zeigt den Niederschlag eines Jahres. Im Juli ist die Säule am höchsten. Was bedeutet das?', 'Im Juli fiel am meisten Regen.', ['Im Juli war es am kältesten.', 'Im Juli wehte der stärkste Wind.', 'Im Juli schien die Sonne am längsten.'], 'Niederschlag ist Wasser, das vom Himmel fällt: Regen, Schnee oder Hagel. Die höchste Säule zeigt die größte Menge.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Eine Wettertabelle zeigt für Freitag ❄️ und minus 3 Grad. Was ziehst du am Freitag an?', 'Winterjacke, Haube und Handschuhe', ['T-Shirt, kurze Hose und Badeschlapfen', 'nur eine dünne Regenjacke', 'Badehose und einen Sonnenhut'], 'Minus 3 Grad ist unter null: Es ist frostig kalt und es kann schneien. Warme Kleidung schützt dich.'),
  ScienceQuestion.item(4, 'Diagramme lesen', 'Ein Diagramm zeigt die Temperatur an einem Sommertag: um 6 Uhr 14 Grad, um 15 Uhr 28 Grad, um 22 Uhr 19 Grad. Warum ist es am Nachmittag am wärmsten?', 'Die Sonne hat Boden und Luft lange erwärmt.', ['In der Nacht scheint die Sonne am stärksten.', 'Am Nachmittag steht der Mond am höchsten.', 'Wolken machen den Nachmittag immer heiß.'], 'Die Sonne wärmt den ganzen Vormittag den Boden, der Boden wärmt die Luft. Darum ist es meist am Nachmittag am wärmsten.'),
  // Klasse 2 (Fachprüfung 2026-11, S-M15): eigene Fragen je Einheit, damit
  // Klasse 2 nicht mit Klasse-1-Fragen aufgefüllt wird.
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Wer sind die Eltern deiner Mutter?', 'deine Großeltern', ['deine Geschwister', 'deine Tanten', 'deine Cousinen'], 'Die Eltern deiner Eltern sind deine Großeltern: Oma und Opa.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Wie nennt man Bruder und Schwester zusammen?', 'Geschwister', ['Großeltern', 'Nachbarn', 'Freunde'], 'Brüder und Schwestern sind Geschwister.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Wie heißt die Schwester deines Vaters?', 'Tante', ['Oma', 'Cousine', 'Nichte'], 'Die Schwester von Vater oder Mutter ist deine Tante.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Wer leitet eine Gemeinde in Österreich?', 'die Bürgermeisterin oder der Bürgermeister', ['die Schuldirektorin oder der Schuldirektor', 'die Briefträgerin oder der Briefträger', 'die Ärztin oder der Arzt'], 'Jede Gemeinde hat eine Bürgermeisterin oder einen Bürgermeister.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Du hast etwas kaputt gemacht. Was ist richtig?', 'es ehrlich sagen und um Entschuldigung bitten', ['es verstecken', 'einem anderen Kind die Schuld geben', 'so tun, als wäre nichts gewesen'], 'Ehrlich sein und sich entschuldigen hilft, den Schaden gemeinsam zu beheben.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Wozu gibt es in der Klasse Klassendienste?', 'damit alle mithelfen und die Klasse in Ordnung bleibt', ['damit ein Kind alles allein macht', 'damit niemand aufräumen muss', 'damit die Pause kürzer wird'], 'Bei Klassendiensten übernimmt jedes Kind eine kleine Aufgabe für alle.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Ein neues Kind kommt in die Klasse. Was hilft ihm?', 'es begrüßen und ihm alles zeigen', ['es nicht beachten', 'über es lachen', 'ihm den Platz wegnehmen'], 'Wer freundlich begrüßt wird, fühlt sich schneller wohl.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Welche Nummer wählst du, wenn du die Polizei brauchst?', '133', ['122', '144', '111'], 'Polizei 133, Feuerwehr 122, Rettung 144. Diese Nummern sind kostenlos.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Was feiern viele Familien in Österreich am 24. Dezember?', 'den Heiligen Abend', ['Ostern', 'den Nationalfeiertag', 'Fasching'], 'Am 24. Dezember ist der Heilige Abend. Viele Familien feiern dann Weihnachten.'),
  ScienceQuestion.item(2, 'Familie und Gemeinschaft', 'Wann ist der österreichische Nationalfeiertag?', 'am 26. Oktober', ['am 1. Mai', 'am 24. Dezember', 'am 1. Jänner'], 'Am 26. Oktober feiert Österreich seinen Nationalfeiertag.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'Welche Jahreszeit kommt nach dem Winter?', 'Frühling', ['Sommer', 'Herbst', 'Advent'], 'Nach dem Winter kommt der Frühling. Der Advent ist keine Jahreszeit.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'In welcher Jahreszeit sind die Tage am längsten?', 'Sommer', ['Frühling', 'Herbst', 'Winter'], 'Im Sommer ist es am längsten hell.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'In welcher Jahreszeit sind die Nächte am längsten?', 'Winter', ['Frühling', 'Sommer', 'Herbst'], 'Im Winter wird es früh dunkel und spät hell.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'In welcher Jahreszeit werden Kürbisse und Weintrauben geerntet?', 'Herbst', ['Frühling', 'Winter', 'Sommer'], 'Im Herbst sind Kürbisse und Trauben reif.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'Was machen Igel im Winter?', 'sie halten Winterschlaf', ['sie fliegen in den Süden', 'sie bauen ein Nest im Baum', 'sie sammeln Nektar'], 'Igel verschlafen den Winter in einem Laubhaufen.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'Wohin fliegen Störche und Schwalben im Herbst?', 'in den warmen Süden', ['in den kalten Norden', 'auf die Berge', 'in den Wald'], 'Zugvögel fliegen im Herbst in wärmere Länder und kommen im Frühling zurück.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'In welcher Jahreszeit kommen viele Tierkinder zur Welt?', 'Frühling', ['Herbst', 'Winter', 'Sommer'], 'Im Frühling gibt es wieder viel Futter. Darum kommen dann viele Tierkinder zur Welt.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'Welches Fest feiern viele Kinder im Frühling?', 'Ostern', ['Weihnachten', 'Nikolaus', 'Erntedank'], 'Ostern ist im Frühling. Erntedank ist im Herbst, Nikolaus und Weihnachten sind im Dezember.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'In welcher Jahreszeit ist der Faschingsdienstag?', 'Winter', ['Frühling', 'Sommer', 'Herbst'], 'Der Fasching endet am Faschingsdienstag, noch im Winter.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'Warum werfen Laubbäume im Herbst ihre Blätter ab?', 'so sparen sie im Winter Wasser', ['weil der Wind zu stark ist', 'weil die Blätter zu schwer werden', 'weil Vögel die Blätter fressen'], 'Über die Blätter verliert ein Baum Wasser. Ohne Blätter kommt er gut durch den Winter.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'In welchen Monaten sind in Österreich die großen Sommerferien?', 'Juli und August', ['Mai und Juni', 'September und Oktober', 'Dezember und Jänner'], 'Die Sommerferien dauern neun Wochen, vor allem im Juli und August. Je nach Bundesland beginnen sie Ende Juni oder im Juli.'),
  ScienceQuestion.item(2, 'Jahreszeiten', 'Welche Blume blüht oft schon, wenn noch Schnee liegt?', 'Schneeglöckchen', ['Sonnenblume', 'Rose', 'Mohn'], 'Schneeglöckchen gehören zu den ersten Blumen des Jahres.'),
  ScienceQuestion.item(2, 'Körper', 'Wie oft am Tag solltest du mindestens die Zähne putzen?', 'zweimal', ['einmal in der Woche', 'nur am Sonntag', 'gar nicht'], 'Putze die Zähne in der Früh und am Abend.'),
  ScienceQuestion.item(2, 'Körper', 'Wie viele Milchzähne hat ein Kind?', '20', ['10', '28', '32'], 'Ein Kind hat 20 Milchzähne. Später wachsen die bleibenden Zähne nach.'),
  ScienceQuestion.item(2, 'Körper', 'Was schützt dein Gehirn?', 'der Schädel', ['die Augenbrauen', 'die Haare', 'die Ohren'], 'Der harte Schädelknochen schützt das Gehirn. Ein Helm schützt zusätzlich.'),
  ScienceQuestion.item(2, 'Körper', 'Was brauchst du, um Arme und Beine zu beugen?', 'Gelenke', ['Fingernägel', 'Haare', 'Zähne'], 'Ellbogen und Knie sind Gelenke. Dort lassen sich Arme und Beine beugen.'),
  ScienceQuestion.item(2, 'Körper', 'Was passiert mit deinem Herz, wenn du schnell läufst?', 'es schlägt schneller', ['es schlägt langsamer', 'es bleibt stehen', 'es schläft ein'], 'Beim Laufen braucht der Körper mehr Sauerstoff. Das Herz schlägt schneller.'),
  ScienceQuestion.item(2, 'Körper', 'Was gibst du bei starker Sonne auf die Haut?', 'Sonnencreme', ['Zahnpasta', 'Spülmittel', 'Wasserfarbe'], 'Sonnencreme schützt die Haut vor Sonnenbrand.'),
  ScienceQuestion.item(2, 'Körper', 'Wohin niest du, wenn du kein Taschentuch hast?', 'in die Armbeuge', ['in die Hand', 'in die Luft', 'auf den Tisch'], 'In der Armbeuge bleiben die Keime und kommen nicht auf deine Hände.'),
  ScienceQuestion.item(2, 'Körper', 'Welche Jause gibt dir lange Kraft?', 'Vollkornbrot mit Käse und ein Apfel', ['Zuckerl und Limonade', 'Chips und Cola', 'nur ein Schokoriegel'], 'Vollkornbrot, Käse und Obst geben dir lange Energie.'),
  ScienceQuestion.item(2, 'Körper', 'Wozu brauchst du deine Muskeln?', 'zum Bewegen', ['zum Hören', 'zum Riechen', 'zum Schmecken'], 'Muskeln ziehen an den Knochen. So kannst du dich bewegen.'),
  ScienceQuestion.item(2, 'Körper', 'Wer hilft dir, wenn ein Zahn wehtut?', 'die Zahnärztin oder der Zahnarzt', ['die Friseurin oder der Friseur', 'die Bäckerin oder der Bäcker', 'die Tischlerin oder der Tischler'], 'Zahnärztinnen und Zahnärzte behandeln kranke Zähne.'),
  ScienceQuestion.item(2, 'Wetter', 'In welcher Einheit messen wir bei uns die Temperatur?', 'Grad Celsius', ['Kilogramm', 'Zentimeter', 'Kilometer je Stunde'], 'Die Temperatur messen wir in Grad Celsius.'),
  ScienceQuestion.item(2, 'Wetter', 'Bei wie viel Grad gefriert Wasser?', 'bei 0 Grad', ['bei 10 Grad', 'bei 50 Grad', 'bei 100 Grad'], 'Bei 0 Grad Celsius gefriert Wasser zu Eis.'),
  ScienceQuestion.item(2, 'Wetter', 'Was nimmst du bei einem Gewitter zuerst wahr?', 'zuerst siehst du den Blitz', ['zuerst hörst du den Donner', 'beides kommt immer genau gleichzeitig', 'den Donner hörst du erst am nächsten Tag'], 'Licht ist schneller als Schall. Darum siehst du den Blitz, bevor du den Donner hörst.'),
  ScienceQuestion.item(2, 'Wetter', 'Was ist Hagel?', 'Eiskörner aus Gewitterwolken', ['warmer Wind, der vor dem Gewitter weht', 'sehr feiner Regen aus hohen Wolken', 'Nebel, der am Boden liegen bleibt'], 'Hagelkörner sind kleine Eiskugeln. Sie können Pflanzen und Autos beschädigen.'),
  ScienceQuestion.item(2, 'Wetter', 'Woraus besteht Schnee?', 'aus Eiskristallen', ['aus weißem Salz', 'aus feinem Staub', 'aus Wattebäuschen'], 'Schneeflocken bestehen aus vielen kleinen Eiskristallen.'),
  ScienceQuestion.item(2, 'Wetter', 'Was sagt dir der Wetterbericht?', 'wie das Wetter in den nächsten Tagen wird', ['wie viele Kinder heute in der Klasse sind', 'welcher Wochentag morgen sein wird', 'wie spät es gerade in Amerika ist'], 'Der Wetterbericht sagt das Wetter für die nächsten Tage voraus.'),
  ScienceQuestion.item(2, 'Wetter', 'Wann entsteht Tau auf der Wiese?', 'in der kühlen Nacht und am frühen Morgen', ['zu Mittag in der Sonne', 'nur bei Gewitter', 'nur an heißen Nachmittagen'], 'Wenn die Luft in der Nacht abkühlt, setzen sich kleine Wassertropfen auf den Gräsern ab.'),
  ScienceQuestion.item(2, 'Wetter', 'Was passiert mit einer Pfütze, wenn lange die Sonne scheint?', 'sie trocknet aus', ['sie wird größer', 'sie gefriert', 'sie wird zu Schnee'], 'Das Wasser verdunstet. Es geht als unsichtbarer Wasserdampf in die Luft.'),
  ScienceQuestion.item(2, 'Wetter', 'Was brauchst du bei starker Sonne im Freien?', 'Sonnenhut und Sonnencreme', ['Haube und Schal', 'Gummistiefel und Regenjacke', 'Handschuhe und Winterjacke'], 'Sonnenhut und Sonnencreme schützen Kopf und Haut.'),
  ScienceQuestion.item(2, 'Wetter', 'Wie nennt man sehr starken Wind?', 'Sturm', ['Nebel', 'Tau', 'Reif'], 'Ein Sturm ist sehr starker Wind. Er kann Äste abbrechen.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Wie viele Stunden hat ein Tag?', '24', ['12', '60', '7'], 'Ein Tag hat 24 Stunden.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Wie viele Minuten hat eine Stunde?', '60', ['24', '100', '30'], 'Eine Stunde hat 60 Minuten.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Welcher Monat hat nur 28 oder 29 Tage?', 'Februar', ['Jänner', 'April', 'Dezember'], 'Der Februar ist der kürzeste Monat.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Welcher Monat kommt vor dem September?', 'August', ['Oktober', 'Juli', 'Juni'], 'Vor dem September kommt der August.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'In welchem Monat beginnt in Österreich das Schuljahr?', 'September', ['Jänner', 'Juni', 'November'], 'Nach den Sommerferien beginnt die Schule im September.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Was bedeutet vorgestern?', 'der Tag vor gestern', ['der Tag nach morgen', 'der heutige Tag', 'die nächste Woche'], 'Von heute aus gehst du zwei Tage zurück: gestern und vorgestern.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Welcher Wochentag liegt zwischen Dienstag und Donnerstag?', 'Mittwoch', ['Montag', 'Freitag', 'Samstag'], 'Dienstag, Mittwoch, Donnerstag: Der Mittwoch liegt in der Mitte der Woche.'),
  ScienceQuestion.item(2, 'Zeit und Kalender', 'Wie viele Wochen hat ein Monat ungefähr?', '4', ['2', '7', '12'], 'Ein Monat hat ungefähr vier Wochen.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Was brauchen Pflanzen außer Wasser zum Wachsen?', 'Licht', ['Dunkelheit', 'Lärm', 'Kälte'], 'Pflanzen brauchen Wasser, Licht, Luft und Nährstoffe aus der Erde.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Welcher Baum trägt Zapfen?', 'Fichte', ['Apfelbaum', 'Birke', 'Kastanie'], 'Fichten sind Nadelbäume. Ihre Samen stecken in den Zapfen.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Wie heißen die Früchte der Eiche?', 'Eicheln', ['Kastanien', 'Zapfen', 'Bucheckern'], 'An der Eiche wachsen Eicheln. Bucheckern wachsen an der Buche.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Welches Gemüse wächst unter der Erde?', 'Karotte', ['Paradeiser', 'Gurke', 'Paprika'], 'Die Karotte ist eine Wurzel und wächst in der Erde. Paradeiser sagt man in Österreich zur Tomate.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Was entsteht aus der Blüte des Apfelbaums?', 'ein Apfel', ['ein Blatt', 'eine Wurzel', 'ein Ast'], 'Wird die Blüte bestäubt, wächst daraus ein Apfel.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Welche Pflanze ist ein Getreide?', 'Weizen', ['Karotte', 'Tulpe', 'Fichte'], 'Weizen ist ein Getreide. Aus seinen Körnern wird Mehl gemahlen.'),
  ScienceQuestion.item(2, 'Pflanzen', 'Wo speichert eine Tulpe Kraft für das nächste Jahr?', 'in der Zwiebel', ['im Blatt', 'in der Blüte', 'im Stängel'], 'Die Tulpenzwiebel bleibt in der Erde. Aus ihr wächst im Frühling eine neue Tulpe.'),
  ScienceQuestion.item(2, 'Verkehr', 'Welche Nummer wählst du, wenn jemand die Rettung braucht?', '144', ['122', '133', '111'], 'Rettung 144, Feuerwehr 122, Polizei 133.'),
  ScienceQuestion.item(2, 'Verkehr', 'Die Fußgängerampel ist ausgefallen. Was machst du?', 'warten und erst gehen, wenn alles frei ist', ['mitten auf der Fahrbahn auf Grün warten', 'ohne zu schauen schnell über die Straße rennen', 'einfach losgehen, die Autos halten schon'], 'Ohne Ampel schaust du selbst nach links und rechts und gehst erst, wenn kein Fahrzeug kommt.'),
  ScienceQuestion.item(2, 'Verkehr', 'Was braucht dein Fahrrad, damit du im Dunkeln gesehen wirst?', 'Licht und Rückstrahler', ['bunte Griffe und Bänder', 'eine laute Hupe', 'einen großen Korb'], 'Mit Licht vorne und hinten und mit Rückstrahlern sehen dich andere rechtzeitig.'),
  ScienceQuestion.item(2, 'Verkehr', 'Wo wartest du auf den Schulbus?', 'an der Haltestelle mit Abstand', ['hinter dem Bus, wo dich niemand sieht', 'zwischen parkenden Autos am Straßenrand', 'direkt auf der Fahrbahn vor dem Bus'], 'An der Haltestelle wartest du mit Abstand, bis der Bus steht.'),
  ScienceQuestion.item(2, 'Verkehr', 'Wo sitzt ein Kind im Auto am sichersten?', 'angeschnallt im Kindersitz', ['auf dem Schoß eines Erwachsenen', 'vorne ohne Gurt', 'im Kofferraum'], 'Kindersitz und Gurt halten dich bei einer Bremsung fest.'),
  ScienceQuestion.item(2, 'Verkehr', 'Du fährst mit dem Roller am Gehsteig. Auf wen nimmst du Rücksicht?', 'auf alle, die zu Fuß gehen', ['auf niemanden', 'nur auf Autos', 'nur auf Hunde'], 'Am Gehsteig haben Fußgängerinnen und Fußgänger Vorrang. Fahr langsam und halte Abstand.'),
  ScienceQuestion.item(2, 'Berufe', 'Welche Nummer hat die Feuerwehr?', '122', ['133', '144', '120'], 'Feuerwehr 122, Polizei 133, Rettung 144.'),
  ScienceQuestion.item(2, 'Berufe', 'Wer unterrichtet die Kinder in der Schule?', 'Lehrerin oder Lehrer', ['Köchin oder Koch', 'Gärtnerin oder Gärtner', 'Pilotin oder Pilot'], 'Lehrerinnen und Lehrer unterrichten in der Schule.'),
  ScienceQuestion.item(2, 'Berufe', 'Wer pflanzt und pflegt Blumen und Bäume?', 'Gärtnerin oder Gärtner', ['Malerin oder Maler', 'Kellnerin oder Kellner', 'Schneiderin oder Schneider'], 'Gärtnerinnen und Gärtner arbeiten mit Pflanzen.'),
  ScienceQuestion.item(2, 'Berufe', 'Wer baut Möbel aus Holz?', 'Tischlerin oder Tischler', ['Bäckerin oder Bäcker', 'Fleischerin oder Fleischer', 'Friseurin oder Friseur'], 'Tischlerinnen und Tischler bauen Tische, Kästen und Sessel aus Holz.'),
  ScienceQuestion.item(2, 'Berufe', 'Wer sorgt am Bauernhof für Tiere und Felder?', 'Bäuerin oder Bauer', ['Verkäuferin oder Verkäufer', 'Polizistin oder Polizist', 'Köchin oder Koch'], 'Bäuerinnen und Bauern versorgen die Tiere und bestellen die Felder.'),
  ScienceQuestion.item(2, 'Tiere', 'Welches Tier hält in den Alpen Winterschlaf?', 'Murmeltier', ['Reh', 'Fuchs', 'Hase'], 'Murmeltiere verschlafen den Winter in ihrem Bau. Reh, Fuchs und Hase bleiben wach.'),
  ScienceQuestion.item(2, 'Tiere', 'Welches Tier lebt in den österreichischen Alpen?', 'Gämse', ['Giraffe', 'Pinguin', 'Känguru'], 'Gämsen klettern in den Bergen der Alpen.'),
  ScienceQuestion.item(2, 'Tiere', 'Was frisst eine Kuh?', 'Gras und Heu', ['Fleisch', 'Fische', 'Insekten'], 'Kühe sind Pflanzenfresser. Sie fressen Gras und im Winter Heu.'),
  ScienceQuestion.item(2, 'Tiere', 'Wie viele Beine hat eine Spinne?', '8', ['6', '4', '10'], 'Spinnen haben acht Beine. Insekten haben sechs.'),
];
